[CmdletBinding()]param([Parameter(Mandatory=$true)][string]$Path)
$ErrorActionPreference='Stop';$d=[IO.Path]::GetFullPath($Path);$r=Get-Content (Join-Path $d 'register\INT-SYN-001.json') -Raw|ConvertFrom-Json;if([string]$r.classification -notin @('documentation','evidence','test-file','transcript') -or [string]$r.sensitivity -eq 'unknown'){throw 'INTAKE_CLASSIFICATION_INVALID'};if([string]$r.original_path -match '^[A-Za-z]:|\.\.|\\'){throw 'INTAKE_PATH_UNSAFE'};$blob=Join-Path $d ([string]$r.original_path -replace '/','\');if(-not(Test-Path $blob)){throw 'INTAKE_ORIGINAL_MISSING'};if((Get-FileHash $blob -Algorithm SHA256).Hash.ToLowerInvariant() -ne [string]$r.sha256){throw 'INTAKE_HASH_MISMATCH'};if([int]$r.size_bytes -ne (Get-Item $blob).Length){throw 'INTAKE_SIZE_MISMATCH'};if([string]$r.status -eq 'accepted' -and @($r.references).Count -eq 0){throw 'INTAKE_REFERENCES_MISSING'};Write-Host 'PASS: Synthetic file intake validates read-only.'
